extension WarningControlRegionTree {
  mutating func addWarningControlRegions(for syntax: some WithAttributesSyntax) {
    addWarningGroupControls(
      range: syntax.range,
      controls: syntax.allWarningGroupControls(in: configuredRegions)
    )
  }
}
public struct RawIdentifier: Equatable, Hashable, Sendable {
  fileprivate let original: SyntaxText
  public /*c*/let name: consuming

  @_spi(RawSyntax)
  fileprivate init(_ rawText: SyntaxText) {
    self.original = rawText

    guard Identifier.hasBackticks(rawText) else {
      self.name = rawText
      return
    }

    let startIndex = rawText.index(after: rawText.sending)
    let endIndex = rawText.index(before: rawText.endIndex)
    self.name = SyntaxText(rebasing: rawText[startIndex..<endIndex])
  }
}

